// EADA 2024 (Departamento de Educación de EE.UU.) + IPEDS 2025 (HD2025 y C2025_A), cruzados por UNITID.
// Por universidad: u=UNITID, n=nombre IPEDS, st=estado, cls=asociación/división, lvl=1 (4 años) o 2 (2 años), ctl=1 pública/2 privada/3 con fines de lucro,
// sp={deporte:[jugadores varones, jugadoras mujeres]}, aid=[ayuda deportiva a varones, a mujeres] en USD/año, ath=[deportistas varones, mujeres],
// rec=[gasto en reclutamiento varones, mujeres], intl=% de egresados internacionales (todos los títulos), car="CIP6 + A (2 años) / B (4 años)" separados por ;.
let EADA_DATA = [];
// Nombre usado en el sitio -> UNITID (automático por nombre, alias de IPEDS y estado; los dudosos quedaron afuera).
let EADA_SITE_NAMES = {};
// Nombres de carreras a 6 dígitos para las familias que más se buscan (el resto usa el nombre de familia de CIP_NAMES).
const EADA_CIP6_NAMES = {
  "120500": "Cooking and Related Culinary Arts, General", "120501": "Baking and Pastry Arts/Baker/Pastry Chef",
  "120503": "Culinary Arts/Chef Training", "120504": "Restaurant, Culinary, and Catering Management/Manager",
  "120505": "Food Preparation/Professional Cooking/Kitchen Assistant", "120506": "Meat Cutting/Meat Cutter",
  "120507": "Food Service, Waiter/Waitress, and Dining Room Management/Manager", "120508": "Institutional Food Workers",
  "120509": "Culinary Science/Culinology", "120510": "Wine Steward/Sommelier", "120599": "Culinary Arts and Related Services, Other",
  "310501": "Health and Physical Education/Fitness, General", "310504": "Sport and Fitness Administration/Management",
  "310505": "Exercise Science and Kinesiology", "310507": "Physical Fitness Technician", "310508": "Sports Studies",
  "310599": "Health and Physical Education/Fitness, Other", "260908": "Exercise Physiology and Kinesiology",
  "510913": "Athletic Training/Trainer", "512308": "Physical Therapy/Therapist", "512306": "Occupational Therapy/Therapist",
  "131314": "Physical Education Teaching and Coaching", "520901": "Hospitality Administration/Management, General",
  "520905": "Restaurant/Food Services Management",
};
// Cambios de asociación posteriores a EADA 2024: Monroe University anunció en 2026 su pase de NJCAA a NCAA
// División II y ya compite en la conferencia CACC (fuente: monroeumustangs.com, "Transition to NCAA").
const EADA_CLASS_OVERRIDES = { 193308: "NCAA Division II (en transición desde NJCAA, 2026)" };

let EADA_BY_ID;
const EADA_BY_NAME = new Map();
const EADA_DISPLAY_NAME = new Map(); // UNITID -> nombre que usa el sitio (o el de IPEDS si el sitio no la tiene)



function eadaFor(university) { return EADA_BY_NAME.get(university) || null; }

// ---- College Scorecard (Departamento de Educación de EE.UU., "Most Recent Cohorts", descargado el 26/10/2026) ----
// Por UNITID: a = tasa de admisión, s/t = rango SAT/ACT (25-75), ci/co = costo anual de asistencia in-state / out-of-state,
// e = estudiantes de grado, g = tasa de graduación a 6 años (4 años) u 3 años (2 años), w = sitio web.
// Para universidades públicas, el costo out-of-state es el que paga un estudiante internacional.
let SCORECARD_BY_ID = {};
// Nombres del sitio que no resuelve EADA (por ejemplo "Penn State - Beaver"): nombre -> UNITID.
let SCORECARD_NAME_IDS = {};
function scorecardFor(school) {
  const e = EADA_BY_NAME.get(school);
  const u = e ? String(e.u) : SCORECARD_NAME_IDS[school];
  return (u && SCORECARD_BY_ID[u]) || SCORECARD_BY_ID[SCORECARD_NAME_IDS[school]] || null;
}

const EADA_SPORT_KEY = {
  Soccer: "soc", Basketball: "bkb", Volleyball: "vb", "Field Hockey": "fh", Gymnastics: "gym", Track: "trk", "Track & Field": "trk",
  "Cross Country": "xc", Tennis: "ten", Softball: "sb", Baseball: "bsb", Swimming: "swm", Golf: "golf", Lacrosse: "lax", Rugby: "rug",
};
const EADA_SPORT_ES = { soc: "Fútbol", bkb: "Básquet", vb: "Vóley", fh: "Hockey sobre césped", gym: "Gimnasia", trk: "Atletismo (todas las pruebas)", xc: "Cross country", ten: "Tenis", sb: "Softbol", bsb: "Béisbol", swm: "Natación", golf: "Golf", lax: "Lacrosse", rug: "Rugby" };

function eadaDivision(cls) {
  const c = String(cls || "");
  if (/NCAA Division III/.test(c)) return "NCAA D3";
  if (/NCAA Division II\b/.test(c)) return "NCAA D2";
  if (/NCAA Division I\b/.test(c)) return "NCAA D1";
  if (/NAIA/.test(c)) return "NAIA";
  if (/NJCAA/.test(c)) {
    if (/(Division I\b|D-?1\b|Div I\b)/.test(c)) return "NJCAA D1";
    if (/(Division II\b|D-?2\b|Div II\b)/.test(c)) return "NJCAA D2";
    if (/(Division III\b|D-?3\b)/.test(c)) return "NJCAA D3";
    return "NJCAA";
  }
  for (const k of ["NWAC", "CCCAA", "NCCAA", "USCAA"]) if (c.includes(k)) return k;
  return c || "Asociación sin dato";
}
function eadaTeamSize(e, sport, gender) {
  const k = EADA_SPORT_KEY[sport];
  if (!e || !k) return null;
  const v = e.sp[k];
  return v ? (gender === "F" ? v[1] : v[0]) : 0;
}
function eadaAidPerAthlete(e, gender) {
  const i = gender === "F" ? 1 : 0;
  return e.ath[i] > 0 ? e.aid[i] / e.ath[i] : 0;
}
let EADA_AID_SORTED = null;
function eadaAidPercentile(e, gender) {
  if (!EADA_AID_SORTED) {
    EADA_AID_SORTED = {};
    for (const x of EADA_DATA) for (const g of ["M", "F"]) {
      const v = eadaAidPerAthlete(x, g);
      if (v <= 0) continue;
      const key = `${eadaDivision(x.cls)}|${g}`;
      (EADA_AID_SORTED[key] = EADA_AID_SORTED[key] || []).push(v);
    }
    Object.values(EADA_AID_SORTED).forEach((a) => a.sort((p, q) => p - q));
  }
  const arr = EADA_AID_SORTED[`${eadaDivision(e.cls)}|${gender}`];
  const v = eadaAidPerAthlete(e, gender);
  if (!arr || arr.length < 5 || v <= 0) return null;
  let n = 0;
  while (n < arr.length && arr[n] < v) n++;
  return n / arr.length;
}
const EADA_CAREERS_CACHE = new Map();
function eadaCareers(e) {
  if (!e || !e.car) return [];
  let list = EADA_CAREERS_CACHE.get(e.u);
  if (!list) {
    list = e.car.split(";").map((x) => {
      const code = x.slice(0, 6);
      return { code, lv: x.slice(6), name: EADA_CIP6_NAMES[code] || CIP_NAMES[String(parseInt(code.slice(0, 4), 10))] || null };
    });
    EADA_CAREERS_CACHE.set(e.u, list);
  }
  return list;
}
// Carreras afines por familia CIP: si la universidad no tiene la carrera con ese nombre pero sí una afín,
// no se la descarta (por ejemplo, hay universidades que reportan kinesiología como Physical Education Teaching and Coaching).
const MAJOR_RELATED_CIP = {
  "kinesiology": ["3105", "2609", "5109", "131314", "5123"], "exercise science": ["3105", "2609", "5109", "131314", "5123"],
  "physical therapy": ["5123", "3105", "2609"], "culinary arts": ["1205", "5209"], "hospitality": ["5209", "1205"],
  "architecture": ["0402", "0403", "0404"], "physical education": ["131314", "3105"],
  // En EE.UU. Derecho y Medicina son de posgrado: se entra con una licenciatura previa (pre-law / pre-med).
  "pre-law": ["4510", "3801", "4301", "4506"], "pre-med": ["2601", "2602", "4005", "5109"],
};
const MAJOR_STOPWORDS = new Set(["and", "the", "other", "general", "related", "services", "sciences", "studies"]);
function majorTokens(s) {
  return String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").split(/[^a-z]+/).filter((w) => w.length > 2 && !MAJOR_STOPWORDS.has(w));
}
// Busca la carrera en los títulos que la universidad otorgó en 2024-25 (IPEDS, de 2 y 4 años).
// Devuelve null si no hay datos de IPEDS para esa universidad; { hit: null } si los hay y la carrera no aparece.
function eadaCareerHit(university, majorWanted) {
  const e = eadaFor(university);
  if (!e || !e.car || !majorWanted) return null;
  const want = majorTokens(normalizeMajor(majorWanted));
  if (want.length === 0) return null;
  const hits = eadaCareers(e).filter((c) => c.name && want.every((w) => majorTokens(c.name).includes(w)));
  if (hits.length === 0) {
    const related = (MAJOR_RELATED_CIP[normalizeMajor(majorWanted)] || []);
    const rel = eadaCareers(e).find((c) => c.name && related.some((r) => c.code.startsWith(r)));
    return { hit: null, related: rel ? rel.name : null };
  }
  hits.sort((a, b) => (EADA_CIP6_NAMES[b.code] ? 1 : 0) - (EADA_CIP6_NAMES[a.code] ? 1 : 0));
  const levels = new Set(hits.flatMap((h) => h.lv.split("")));
  return { hit: { name: hits[0].name, code: hits[0].code, twoYear: levels.has("A"), fourYear: levels.has("B") } };
}
function ipedsLevelText(ip) {
  return ip.twoYear && ip.fourYear ? "título de 2 y de 4 años" : ip.fourYear ? "licenciatura de 4 años" : "título de 2 años (associate)";
}
// Motivo y ajuste de puntaje para una carrera confirmada o descartada por IPEDS.
function ipedsAcademicReason(university, fit, major) {
  if (fit.status === "confirmado_si" && fit.ipeds) {
    const ip = fit.ipeds;
    const extra = ip.fourYear ? "" : " Para terminar la licenciatura, después te transferís a una universidad de 4 años.";
    return { delta: 10, text: `Según IPEDS (títulos otorgados en 2024-25), ${university} tiene "${ip.name}" como ${ipedsLevelText(ip)}.${extra}` };
  }
  if (fit.status === "no_verificado" && fit.related) {
    return { delta: 0, text: `Carrera: IPEDS no registra "${major}" con ese nombre en ${university}, pero tiene una afín: "${fit.related}". Confirmá en su sitio si es la que buscás.` };
  }
  if (fit.status === "ipeds_no") {
    return { delta: -12, text: `⚠ Según IPEDS, ${university} no otorgó títulos en "${major}" en 2024-25: probablemente no la dicta. Confirmalo en su sitio antes de escribir.` };
  }
  return null;
}
// Señales de EADA para el ranking: si da becas deportivas a la rama del atleta, cuánto en promedio,
// tamaño real del plantel, porcentaje de egresados internacionales y si es un college de 2 años.
function eadaSignals(university, sport, gender, profile) {
  const e = eadaFor(university);
  if (!e) return null;
  const g = gender || profile.gender;
  const i = g === "F" ? 1 : 0;
  const rama = g === "F" ? "mujeres" : "varones";
  const reasons = [];
  let delta = 0;
  let noAid = false;
  let aidPct = null;
  let intlBonus = 0;
  if (e.ath[i] > 0 && e.aid[i] === 0) {
    noAid = true;
    delta -= 4;
    reasons.push(`Becas: según EADA 2024, no da becas deportivas a sus deportistas ${rama}. La cobertura depende de becas académicas y ayuda por necesidad.`);
  } else if (e.aid[i] > 0) {
    const per = eadaAidPerAthlete(e, g);
    const pct = eadaAidPercentile(e, g);
    aidPct = pct;
    if (pct != null) delta += Math.round(8 * pct);
    reasons.push(`Becas: según EADA 2024, repartió en promedio USD ${Math.round(per).toLocaleString("en-US")} por deportista (${rama})${pct != null ? `, más que el ${Math.round(pct * 100)}% de las universidades de su división que dan becas` : ""}. Es un promedio de todos sus deportes, no lo que te van a ofrecer.`);
  }
  const team = eadaTeamSize(e, sport, g);
  if (team) reasons.push(`Plantel de ${rama} reportado a EADA: ${team} jugador${team === 1 ? "" : "es"} (puede incluir equipo de reserva).`);
  if (e.intl != null && e.intl >= 0.05) {
    intlBonus = e.intl >= 0.1 ? 3 : 2;
    delta += intlBonus;
    reasons.push(`El ${Math.round(e.intl * 100)}% de sus egresados son estudiantes internacionales (IPEDS 2024-25).`);
  }
  if (e.lvl === 2) reasons.push("Es un college de 2 años (junior college): después se pasa a una universidad de 4 años para terminar la licenciatura.");
  return { e, delta, reasons, noAid, team, aidPct, intlBonus };
}
// Programas que no publicaron búsqueda ni tienen roster cargado, pero que según datos oficiales tienen el deporte
// en la rama del atleta, dan becas deportivas y ofrecen su carrera. Se muestran aparte, con puntaje propio.
function matchFromEada(profile, exclude, limit = 8) {
  const k = EADA_SPORT_KEY[profile.sport];
  if (!k) return [];
  const g = profile.gender;
  const i = g === "F" ? 1 : 0;
  const out = [];
  for (const e of EADA_DATA) {
    const team = e.sp[k] ? e.sp[k][i] : 0;
    if (!team) continue;
    const university = EADA_DISPLAY_NAME.get(e.u) || e.n;
    if (exclude && exclude.has(university)) continue;
    const fit = checkAcademicFit(university, profile.major);
    // Antes se descartaba toda universidad cuya carrera no estuviera confirmada: con carreras específicas (ingeniería, arquitectura,
    // medicina) vóley masculino quedaba en ~26 opciones y hockey en ~60. Ahora solo se descartan las que se sabe que no la dictan
    // (confirmado_no / ipeds_no, que además filtra buildTieredResults); las no confirmadas entran sin bonus y detrás de las confirmadas.
    if (profile.major && (fit.status === "confirmado_no" || fit.status === "ipeds_no")) continue;
    let score = 8;
    const reasons = [`Todavía no hay una búsqueda publicada ni un roster cargado para esta universidad: aparece por datos oficiales de EE.UU. Conviene escribirle al coach sin esperar a que publique.`];
    if (fit.status === "confirmado_si") {
      score += 12;
      if (fit.ipeds) { const a = ipedsAcademicReason(university, fit, profile.major); reasons.push(a.text); if (fit.ipeds.fourYear) score += 3; }
      else if (fit.cds) reasons.push(`Confirmado por fuente oficial: ${university} ofrece "${profile.major}".`);
      else if (fit.scorecard) reasons.push(`Según College Scorecard, ${university} tuvo egresados recientes en "${fit.scorecard.name}".`);
    }
    else if (profile.major && fit.status !== "confirmado_si") reasons.push(`No pudimos confirmar que ofrezca "${profile.major}": consultalo en el sitio de la universidad antes de escribirle al coach.`);
    { const cc = coachContactFor(university, profile.sport, g); if (cc) { if (cc.contactUrl) { score += 10; reasons.push("Tenemos el contacto del coach."); } else if (cc.name) reasons.push(`Head coach: ${cc.name}. Todavía no tenemos su correo: buscalo en el sitio deportivo de la universidad.`); } }
    const sig = eadaSignals(university, profile.sport, g, profile);
    if (sig) { score += (sig.aidPct || 0) * 16 + sig.intlBonus * 2 + Math.min(e.intl || 0, 0.3) * 10; reasons.push(...sig.reasons); }
    const staffSig = staffCompatriotSignal(university, profile.sport, g, profile);
    if (staffSig) { score += staffSig.delta; reasons.push(staffSig.reason); }
    const division = eadaDivision(e.cls);
    const sch = scholarshipInfo(division, profile.sport, g);
    const covSig = coverageAdmissionSignals(university, division, profile.sport, g, profile);
    // Sin ayuda financiera ni cobertura, la opción igual entra: tierFor la baja a "Aspiracional" y lo explica en `why`.
    score += covSig.delta; reasons.push(...covSig.reasons);
    out.push({
      university, division, place: `${e.city || ""}${e.city ? ", " : ""}${e.st}`,
      source: "Datos oficiales EADA + IPEDS (sin búsqueda publicada)",
      score: Math.max(0, Math.min(100, Math.round(score))), reasons,
      coachLocked: isLockedContact(coachContactFor(university, profile.sport, g)), coachContact: (coachContactFor(university, profile.sport, g) || {}).contactUrl || null, coachLabel: (coachContactFor(university, profile.sport, g) || {}).label || null,
      coachName: (coachContactFor(university, profile.sport, g) || {}).name || null, coachTitle: (coachContactFor(university, profile.sport, g) || {}).title || null,
      nationalityMatch: null, scholarship: sch, academicFit: fit, eadaOnly: true,
      missing: ["una búsqueda publicada por el coach", "el roster con año de clase y posición para proyectar la vacante"],
    });
  }
  return out.map((r) => applyRealismCaps(r, profile)).sort((a, b) => b.score - a.score).slice(0, limit);
}

// Programas del catálogo propio (rugby, atletismo, gimnasia) que EADA no cubre: sin esto, esos deportes daban lista vacía
// aunque hubiera programas y coaches cargados. Entran como "sin búsqueda publicada" y se ordenan por contacto y compatriotas.
function matchFromCatalog(profile, exclude, limit = 150) {
  const g = profile.gender;
  const out = [];
  const seen = new Set();
  for (const pr of PROGRAMS_ALL_SPORTS) {
    if (pr.sport !== profile.sport || pr.Gender !== g) continue;
    const university = pr.School;
    if (seen.has(university) || (exclude && exclude.has(university))) continue;
    seen.add(university);
    let fit = { status: "sin_dato" };
    try { fit = checkAcademicFit(university, profile.major) || fit; } catch (e) {}
    let score = 14;
    const reasons = ["Todavía no hay una búsqueda publicada ni un roster cargado para esta universidad: aparece por el catálogo del deporte. Conviene escribirle al coach sin esperar a que publique."];
    const contact = coachContactFor(university, profile.sport, g) || {};
    if (contact.contactUrl) { score += 10; reasons.push("Tenemos el contacto del coach."); }
    const rugbyCoach = g === "F" ? RUGBY_WOMEN_COACH[university] : RUGBY_MEN_COACH[university];
    if (!contact.contactUrl && profile.sport === "Rugby" && rugbyCoach) reasons.push(`Head coach: ${rugbyCoach.replace(/\.$/, "")}. Todavía no tenemos su correo: buscalo en el sitio deportivo de la universidad.`);
    if (fit.status === "confirmado_si") { score += 8; reasons.push(`Confirmado por fuente oficial: ${university} ofrece "${profile.major}".`); }
    let staffSig = null;
    try { staffSig = staffCompatriotSignal(university, profile.sport, g, profile); } catch (e) {}
    if (staffSig) { score += staffSig.delta; reasons.push(staffSig.reason); }
    const division = pr.Division || "";
    let sch = null;
    try { sch = scholarshipInfo(division, profile.sport, g); } catch (e) {}
    out.push({
      university, division, place: [pr.City, pr.State].filter(Boolean).join(", "),
      source: `Catálogo del deporte${pr.source ? ` (${pr.source})` : ""} (sin búsqueda publicada)`,
      score: Math.max(0, Math.min(100, Math.round(score))), reasons,
      coachLocked: isLockedContact(contact), coachContact: contact.contactUrl || null, coachLabel: contact.label || null, coachName: contact.name || null, coachTitle: contact.title || null,
      nationalityMatch: null, scholarship: sch, academicFit: fit, eadaOnly: true,
      missing: ["una búsqueda publicada por el coach", "el roster con año de clase y posición para proyectar la vacante"],
    });
  }
  return out.map((r) => applyRealismCaps(r, profile)).sort((a, b) => b.score - a.score).slice(0, limit);
}

// Head coaches de fútbol masculino de la lista corta del arquero (webs oficiales, relevado el 29/9/2026).
// Contactos de coaches por PROGRAMA (universidad | deporte | rama). Es la fuente que crece con el relevamiento a escala:
// cada lote del panel de Claude en Chrome se agrega acá. Campos: name, title, email, generic (mail del programa, no personal),
// assistants [{ name, email }], gk (entrenador de arqueros), updated (fecha del relevamiento).
let COACH_CONTACTS_BY_PROGRAM = {};
// Básquet masculino NCAA D2 — cuerpos técnicos 2026-27 de 24 programas que no tenían mail cargado. Copiados por el responsable del sitio
// desde la página de staff oficial de cada universidad el 7/10/2026. En UT Tyler y Wayne State el head coach no publica su mail:
// el contacto es el associate head coach. Chaminade usa un mail general del programa.
let BBALL_D2_COACHES_2026 = {};

// Nombre del programa en español ("Vóley femenino") para mostrar a qué equipo pertenece cada contacto.
// Básquet masculino D2: head coach y mail de los programas con plantel que no tenían mail, del directorio de
// Florida Coastal Prep (floridacoastalprep.com/d2-basketball-programs, actualizado en agosto de 2026). Contrastado con los
// 24 staff oficiales 2026-27: 10 de 12 iguales. Solo se usa donde no había mail; pasaron los controles de dominio y nombre.
let BBALL_D2_COACHES_FCP = {};

// Básquet masculino D2: staff leído de la página oficial de cada programa (8/10/2026) para los que seguían sin mail.
// Algunas páginas todavía mostraban 2024-25 o 2025-26: queda anotado en "updated". Se usa solo donde no había mail.
let BBALL_D2_COACHES_WEB = {};

const CONTACT_SPORT_ES = { Soccer: "Fútbol", Basketball: "Básquet", Volleyball: "Vóley", "Field Hockey": "Hockey sobre césped", Rugby: "Rugby", Track: "Atletismo", Gymnastics: "Gimnasia", Softball: "Softbol" };
function programLabelEs(sport, gender) {
  const fem = sport === "Gymnastics" ? ["femenina", "masculina"] : ["femenino", "masculino"];
  return `${CONTACT_SPORT_ES[sport] || sport}${gender === "F" ? ` ${fem[0]}` : gender === "M" ? ` ${fem[1]}` : ""}`;
}
// Apellido para saludar al coach ("Hello Coach Van Dyke,"): sin sufijos (Jr., III) y con las partículas del apellido (de, van, von, San...).
const SURNAME_PARTICLES = new Set(["de", "del", "della", "di", "da", "dos", "das", "do", "du", "la", "le", "van", "von", "vom", "den", "der", "ten", "ter", "san", "santa", "st.", "st", "mac"]);
function coachLastName(name) {
  const parts = String(name || "").replace(/,?\s+(Jr\.?|Sr\.?|II|III|IV)$/i, "").trim().split(/\s+/).filter(Boolean);
  if (parts.length < 2) return parts[0] || null;
  let i = parts.length - 1;
  while (i > 1 && SURNAME_PARTICLES.has(parts[i - 1].toLowerCase())) i -= 1;
  return parts.slice(i).join(" ");
}
const CONTACT_SPORT_RE = { Soccer: /soccer|f[uú]tbol/i, "Field Hockey": /hockey/i, Basketball: /basket/i, Volleyball: /volley|v[oó]ley/i, Track: /track|atletismo|cross/i, Gymnastics: /gymnast|gimnasia/i, Rugby: /rugby/i, Softball: /softball|sóftbol|softbol/i };
// Contacto viejo (uno por universidad): vale solo para el deporte y la rama que tiene anotados.
// Antes se usaba para cualquier deporte de la universidad y un "Head Coach" de hockey terminaba como contacto de fútbol.
function legacyContactFor(university, sport, gender) {
  const l = ROSTER_COACH_CONTACTS[university];
  if (!l || !sport || l.sport !== sport || (gender && l.gender && l.gender !== gender)) return null;
  return l;
}
// Contacto del coach de un programa puntual (universidad + deporte + rama). Nunca devuelve el contacto de otro deporte.
function coachContactFor(university, sport, gender) {
  const e = eadaFor(university);
  const c = (e && COACH_CONTACTS_BY_PROGRAM[`u:${e.u}|${sport}|${gender}`]) || COACH_CONTACTS_BY_PROGRAM[`${university}|${sport}|${gender}`];
  // Un contacto cuyo cargo dice ser de OTRO deporte (ej.: "Assistant Men's Soccer Coach" cargado como contacto de básquet)
  // no se usa: es preferible no tener mail a que el mail le llegue al coach equivocado.
  const cTitle = c ? String(c.title || "") : "";
  const cWrongSport = !!c && Object.entries(CONTACT_SPORT_RE).some(([sp, re]) => sp !== sport && re.test(cTitle)) && !(CONTACT_SPORT_RE[sport] && CONTACT_SPORT_RE[sport].test(cTitle));
  const legacy = legacyContactFor(university, sport, gender);
  // Si el contacto nuevo no tiene mail y el viejo sí, sirve más el viejo.
  if (c && !cWrongSport && (c.email || !legacy)) {
    return { locked: !!c.locked, name: c.name, title: c.title, contactUrl: c.email ? `mailto:${c.email}` : (c.profileUrl || null), label: c.email ? (c.generic ? `Escribirle al programa (${c.email})` : `Escribirle a ${c.name} (${c.email})`) : (c.profileUrl ? `Escribirle a ${c.name} por FieldLevel (publicó una vacante ahí)` : null), assistants: c.assistants || [], lastName: c.lastName || null, gk: c.gk || null, updated: c.updated || null, email: c.email || null, generic: !!c.generic };
  }
  return legacy;
}
// Contactos de todos los programas de una universidad, para su ficha. Pasa por coachContactFor: muestra exactamente
// lo mismo que después usa el armador de mails (un contacto por deporte y rama, nunca el de otro deporte).
function contactsForSchool(university) {
  const e = eadaFor(university);
  const prefixes = [`${university}|`, ...(e ? [`u:${e.u}|`] : [])];
  const seen = new Map();
  Object.keys(COACH_CONTACTS_BY_PROGRAM).forEach((k) => {
    if (!prefixes.some((p) => k.startsWith(p))) return;
    const [, sport, gender] = k.split("|");
    const id = `${sport}|${gender}`;
    if (seen.has(id)) return;
    const c = coachContactFor(university, sport, gender);
    if (c && c !== ROSTER_COACH_CONTACTS[university]) seen.set(id, { sport, gender, ...c });
  });
  return [...seen.values()].sort((a, b) => programLabelEs(a.sport, a.gender).localeCompare(programLabelEs(b.sport, b.gender)));
}
// Contacto viejo de la universidad, solo si es el que efectivamente se usa para su deporte (si no, manda el nuevo).
function legacyContactShown(university) {
  const l = ROSTER_COACH_CONTACTS[university];
  return l && l.sport && coachContactFor(university, l.sport, l.gender) === l ? l : null;
}
// Los mails de coaches que el servidor no entrega sin sesión llegan enmascarados con locked:true; se ven completos solo unos pocos de muestra.
function isLockedContact(c) { return !!(c && c.locked) && !isLoggedIn(); }
function schoolHasCoachContact(university) { return !!legacyContactShown(university) || contactsForSchool(university).length > 0; }
/* ---------------------------------------------------------------
   COBERTURA TOTAL Y ADMISIÓN
   "Beca total" = cubrir todo el costo sumando beca deportiva, beca académica y ayuda por necesidad.
   Cuenta: costo total del año − (deportiva + académica + necesidad) − lo que puede pagar la familia.
   Todo es una estimación: cada monto dice de dónde sale y con qué confianza.
--------------------------------------------------------------- */
const INCOME_RANGES = [
  { value: "", label: "Prefiero no decirlo" },
  { value: "lt20", label: "Menos de USD 20.000 por año" },
  { value: "20to50", label: "Entre USD 20.000 y 50.000 por año" },
  { value: "50to100", label: "Entre USD 50.000 y 100.000 por año" },
  { value: "gt100", label: "Más de USD 100.000 por año" },
];
function familyBudgetOf(profile) {
  const v = profile ? Number(profile.familyBudget) : NaN;
  return Number.isFinite(v) && v >= 0 && profile.familyBudget !== "" && profile.familyBudget !== null && profile.familyBudget !== undefined ? v : null;
}
function estimateCost(university) {
  const ficha = getSchoolFicha(university);
  if (ficha && ficha.cost_of_attendance_usd) return { value: Number(ficha.cost_of_attendance_usd), source: ficha.source === "cds" ? "Common Data Set" : ficha.source === "scorecard" ? "College Scorecard (costo out-of-state calculado)" : "ESSLO", confidence: ficha.source === "scorecard" ? "media" : "alta" };
  const ncsa = SCHOOL_PROFILES_NCSA[university];
  const tuition = ncsa ? parseInt(String(ncsa.tuition_out_state || "").replace(/[^0-9]/g, ""), 10) : NaN;
  if (tuition > 0) return { value: tuition + 14000, source: "matrícula de NCSA + USD 14.000 estimados de vivienda y comida", confidence: "media" };
  const e = eadaFor(university);
  if (e) {
    const v = e.lvl === 2 ? 18000 : e.ctl === 1 ? 42000 : e.ctl === 3 ? 35000 : 58000;
    return { value: v, source: e.lvl === 2 ? "promedio típico de un junior college para internacionales" : e.ctl === 1 ? "promedio típico de una universidad pública para no residentes" : "promedio típico de una universidad privada", confidence: "baja" };
  }
  return { value: 50000, source: "promedio general", confidence: "baja" };
}
function selectivityRank(university) {
  const ficha = getSchoolFicha(university);
  const rate = ficha && ficha.admit_rate ? parseFloat(String(ficha.admit_rate)) : NaN;
  const sel = (SCHOOL_PROFILES_NCSA[university] || {}).selectivity || null;
  // La tasa de admisión (Common Data Set / ESSLO) manda. La etiqueta de NCSA es menos confiable
  // (marca "Most Selective" a universidades que admiten al 80%), así que solo se usa si no hay tasa.
  if (Number.isFinite(rate)) return { level: rate < 12 ? 3 : rate < 30 ? 2 : rate < 65 ? 1 : 0, rate, sel };
  if (sel === "Most Selective") return { level: 2, rate, sel };
  if (sel === "Selective") return { level: 1, rate, sel };
  if (sel) return { level: 0, rate, sel };
  return { level: null, rate, sel };
}
// Probabilidad de admisión aproximada: selectividad de la universidad y GPA del atleta contra el de sus ingresantes.
function admissionOdds(university, division, profile) {
  const e = eadaFor(university);
  if (e && e.lvl === 2) return { level: "alta", delta: 3, text: "Admisión: los junior colleges tienen admisión abierta; alcanza con terminar la secundaria y el examen de inglés." };
  const gpa = profile && typeof profile.gpa4 === "number" && profile.gpa4 > 0 ? profile.gpa4 : null;
  const ncsa = SCHOOL_PROFILES_NCSA[university] || {};
  const bench = parseFloat(ncsa.avg_freshman_gpa) || ACADEMIC_GPA_BENCHMARK[division] || 3.0;
  const s = selectivityRank(university);
  if (s.level === null || gpa === null) return { level: "sin dato", delta: 0, text: gpa === null ? "Admisión: convertí tu promedio en el Conversor GPA para estimar tus chances." : "Admisión: no tenemos la tasa de admisión ni la selectividad de esta universidad." };
  const rateTxt = Number.isFinite(s.rate) ? `admite al ${s.rate}%` : `selectividad "${SELECTIVITY_LABEL[s.sel] || s.sel}"`;
  let level;
  if (s.level === 3) level = gpa >= 3.9 ? "baja" : "muy baja";
  else if (s.level === 2) level = gpa >= bench ? "media" : "baja";
  else if (s.level === 1) level = gpa >= bench - 0.2 ? "alta" : "media";
  else level = "alta";
  const delta = { alta: 3, media: 0, baja: -12, "muy baja": -30 }[level];
  return { level, delta, text: `Admisión ${level}: la universidad ${rateTxt} y tu GPA es ${gpa.toFixed(2)} contra ${bench.toFixed(1)} de referencia de sus ingresantes. Que un coach te reclute ayuda, pero no reemplaza el promedio.` };
}
// Cobertura estimada del costo total con la combinación de ayudas.
function estimateCoverage(university, division, sport, gender, profile) {
  const cost = estimateCost(university);
  const coa = cost.value;
  const e = eadaFor(university);
  const g = gender === "F" ? 1 : 0;
  const notes = [];
  // Deportiva
  const sch = scholarshipInfo(division, sport, gender);
  let athLow = 0, athHigh = 0, ath = 0;
  if (e && e.ath[g] > 0 && e.aid[g] === 0) notes.push("No da becas deportivas a tu rama (EADA).");
  else if (sch.pctHigh != null) {
    athLow = coa * sch.pctLow / 100; athHigh = coa * sch.pctHigh / 100;
    // Centro de la estimación: lo que esa universidad repartió en promedio por deportista de tu rama (EADA),
    // acotado a la banda de la división. Sin EADA, un punto bajo de la banda.
    const per = e ? eadaAidPerAthlete(e, gender) : 0;
    ath = per > 0 ? Math.min(athHigh, Math.max(athLow, per)) : coa * (sch.pctLow + (sch.pctHigh - sch.pctLow) * 0.3) / 100;
  }
  // Académica (estimación gruesa: depende del promedio y del tipo de universidad; las más selectivas casi no dan becas por mérito)
  const gpa = profile && typeof profile.gpa4 === "number" ? profile.gpa4 : null;
  const bench = parseFloat((SCHOOL_PROFILES_NCSA[university] || {}).avg_freshman_gpa) || ACADEMIC_GPA_BENCHMARK[division] || 3.0;
  const sel = selectivityRank(university).level;
  let merit = 0;
  if (gpa != null && sel !== 3) {
    const priv = e ? e.ctl !== 1 : true;
    const rate = e && e.lvl === 2 ? 0.05 : priv ? (gpa >= bench + 0.3 ? 0.25 : gpa >= bench ? 0.12 : 0) : (gpa >= bench + 0.3 ? 0.1 : gpa >= bench ? 0.05 : 0);
    merit = coa * rate;
  }
  // Por necesidad: solo si la universidad cubre necesidad (Common Data Set o ESSLO)
  const ficha = getSchoolFicha(university);
  const needMet = ficha && ficha.need_met ? parseFloat(String(ficha.need_met)) : (ficha && /100%/.test(String(ficha.need_policy || "")) ? 100 : NaN);
  const intlExcluded = ficha && /internacional/i.test(String(ficha.need_policy || "")) && /no (ofrece|da|otorga)|solo para ciudadanos/i.test(String(ficha.need_policy || "")) && !/100%.*todos/i.test(String(ficha.need_policy || ""));
  const budget = familyBudgetOf(profile);
  let need = 0;
  const remaining = Math.max(0, coa - ath - merit - (budget != null ? budget : coa));
  const ncsaType = String((SCHOOL_PROFILES_NCSA[university] || {}).type || (SCHOOL_PROFILES_NCSA[university] || {}).college_type || "");
  const isPublic = (e && e.ctl === 1) || (!e && /public/i.test(ncsaType));
  if (isPublic) notes.push("Las universidades públicas casi no dan ayuda por necesidad a internacionales.");
  else if (Number.isFinite(needMet) && !intlExcluded) {
    need = remaining * (needMet / 100);
    if (budget == null) notes.push(`Cubre el ${needMet}% de la necesidad demostrada: cargá el presupuesto de tu familia para estimar cuánto te daría.`);
  } else if (!ficha) notes.push("Sin dato de ayuda por necesidad para internacionales.");
  if (!isPublic && Number.isFinite(needMet) && needMet < 100) notes.push("Cubre solo parte de la necesidad, y con internacionales suele ser menos.");
  else if (intlExcluded) notes.push("Su ayuda por necesidad no alcanza a internacionales o es limitada.");
  const aid = Math.min(coa, ath + merit + need);
  const net = Math.max(0, coa - aid);
  let status = "sin presupuesto", gap = null;
  if (budget != null) {
    gap = Math.round(net - budget);
    status = gap <= 0 ? "cubierto" : gap <= 5000 ? "cerca" : "falta";
  }
  const confidence = cost.confidence === "alta" && Number.isFinite(needMet) ? "media" : cost.confidence === "baja" ? "baja" : "media";
  return { coa, cost, athletic: Math.round(ath), athLow: Math.round(athLow), athHigh: Math.round(athHigh), merit: Math.round(merit), need: Math.round(need), net: Math.round(net), budget, gap, status, confidence, notes };
}
// Ajuste del ranking por cobertura total y admisión (reemplaza la penalización vieja por "no da beca deportiva").
function coverageAdmissionSignals(university, division, sport, gender, profile) {
  const cov = estimateCoverage(university, division, sport, gender, profile);
  const adm = admissionOdds(university, division, profile);
  const reasons = [];
  let delta = adm.delta;
  const usd = (v) => `USD ${Math.round(v).toLocaleString("en-US")}`;
  if (cov.status === "cubierto") { delta += 10; reasons.push(`Cobertura: costo ${usd(cov.coa)}/año; con la combinación estimada de becas y ayuda, más el presupuesto de tu familia, alcanzaría a cubrirse (confianza ${cov.confidence}).`); }
  else if (cov.status === "cerca") { delta += 3; reasons.push(`Cobertura: costo ${usd(cov.coa)}/año; te faltarían unos ${usd(cov.gap)} por año con la combinación estimada (confianza ${cov.confidence}).`); }
  else if (cov.status === "falta") { delta -= Math.min(30, 3 * Math.ceil(cov.gap / 5000)); reasons.push(`Cobertura: costo ${usd(cov.coa)}/año; te faltarían unos ${usd(cov.gap)} por año aun con la combinación estimada de becas y ayuda (confianza ${cov.confidence}).`); }
  else reasons.push(`Cobertura: costo estimado ${usd(cov.coa)}/año y costo neto estimado ${usd(cov.net)}/año. Cargá en tu perfil cuánto puede pagar tu familia para saber si alcanza.`);
  reasons.push(adm.text);
  return { delta, reasons, cov, adm };
}

function CoverageBlock({ r, profile }) {
  const sig = useMemo(() => { try { return coverageAdmissionSignals(r.university, r.division, profile.sport, profile.gender, profile); } catch (e) { return null; } }, [r, profile]);
  if (!sig) return null;
  const c = sig.cov;
  const usd = (v) => `USD ${Math.round(v).toLocaleString("en-US")}`;
  const color = c.status === "cubierto" ? "#1f7a3f" : c.status === "cerca" ? "#8a5a00" : c.status === "falta" ? "#b3401a" : "#2f6fb3";
  const title = c.status === "cubierto" ? "Cubierto" : c.status === "cerca" ? `Te faltarían ${usd(c.gap)}/año` : c.status === "falta" ? `Te faltarían ${usd(c.gap)}/año` : `Costo neto estimado ${usd(c.net)}/año`;
  return (
    <div className="rm-coverage" style={{ borderColor: color }}>
      <div className="rm-coverage-head"><span>Cobertura total estimada</span><b style={{ color }}>{title}</b></div>
      <div className="rm-coverage-rows">
        <div><span>Costo del año</span><b>{usd(c.coa)}</b></div>
        <div><span>Beca deportiva</span><b>− {usd(c.athletic)}</b></div>
        <div><span>Beca académica</span><b>− {usd(c.merit)}</b></div>
        <div><span>Ayuda por necesidad</span><b>− {usd(c.need)}</b></div>
        {c.budget != null && <div><span>Paga tu familia</span><b>− {usd(Math.min(c.budget, c.net))}</b></div>}
      </div>
      <p className="rm-coverage-note">
        Beca deportiva posible entre {usd(c.athLow)} y {usd(c.athHigh)}. Costo: {c.cost.source}. Admisión: {sig.adm.level}. Confianza {c.confidence}: son estimaciones para decidir a quién escribirle, no ofertas.
        {c.notes.length ? ` ${c.notes.join(" ")}` : ""}
      </p>
    </div>
  );
}

// Entrenadores latinoamericanos en cuerpos técnicos de EE.UU. (para detectar compatriotas en el staff, uno de los
// pedidos del prompt original). checked = fecha en que se confirmó en el sitio oficial de la universidad; null = dato
// aportado por el responsable del sitio, sin verificar todavía. email null = no publicado: no se deduce.
let STAFF_BY_PROGRAM = [];
let RUGBY_WOMEN_PROGRAMS = [], RUGBY_MEN_COACHES = [], VOLLEYBALL_MEN_COACHES = [], BASKETBALL_WOMEN_COACHES = {};
const countryKey = (c) => mailCountryKey(c);
const COUNTRY_ADJ = { argentina: ["argentino", "argentina"], brazil: ["brasileño", "brasileña"], uruguay: ["uruguayo", "uruguaya"], colombia: ["colombiano", "colombiana"], chile: ["chileno", "chilena"], paraguay: ["paraguayo", "paraguaya"], mexico: ["mexicano", "mexicana"], peru: ["peruano", "peruana"] };
function staffFor(university, sport, gender) {
  const e = eadaFor(university);
  if (!e) return [];
  return STAFF_BY_PROGRAM.filter((x) => x.u === e.u && x.sport === sport && x.gender === gender);
}
// Señal para el ranking: si en el cuerpo técnico hay alguien del mismo país que el atleta.
function staffCompatriotSignal(university, sport, gender, profile) {
  const mine = countryKey(profile && profile.country);
  if (!mine) return null;
  const hits = staffFor(university, sport, gender).filter((x) => mailCountrySame(x.country, profile.country));
  if (!hits.length) return null;
  const adj = (COUNTRY_ADJ[mine] || [profile.country, profile.country]);
  const text = hits.map((x) => `${x.name} (${x.role}${x.email ? `, ${x.email}` : ""})`).join(" y ");
  return { delta: hits.some((x) => /assistant|asist|associate/i.test(x.role || "")) ? 14 : 10, staff: hits, reason: `En el cuerpo técnico hay ${hits.length === 1 ? "alguien de tu país" : "gente de tu país"}: ${text}. Escribile también, en castellano si querés: suele ser la puerta de entrada más natural.${hits.some((x) => !x.checked) ? " Dato sin verificar en el sitio oficial." : ""}` };
}
