function useSportCalendarStatus(sport, division) {
  const cal = SPORT_CALENDARS[sport];
  if (!cal) return null;
  const today = new Date();
  const toDate = (s) => new Date(s + "T00:00:00");
  const events = division ? cal.events.filter((e) => e.div === division) : cal.events;
  const active = events.filter((e) => toDate(e.start) <= today && today <= new Date(e.end + "T23:59:59.999"));
  const upcoming = events
    .filter((e) => toDate(e.start) > today)
    .sort((a, b) => toDate(a.start) - toDate(b.start))[0];
  return { active, upcoming, cal };
}

const PERIOD_TYPE_LABEL = { dead: "Período Muerto", quiet: "Período Silencioso", shutdown: "Recruiting Shutdown", evaluation: "Período de Evaluación", contact: "Período de Contacto", signing: "Ventana de Firma" };
const PERIOD_TYPE_COLOR = { contact: "#1f7a3f", dead: "#c0392b", quiet: "#d98c1f", shutdown: "#2b2b2b", evaluation: "#2f6fb3", signing: "#6a3fb3" };

function pad2(n) { return String(n).padStart(2, "0"); }
function isoDate(y, m, d) { return `${y}-${pad2(m + 1)}-${pad2(d)}`; }

// Todos los meses (año-mes) cubiertos por al menos un evento del deporte, en orden —
// así el eje de meses no depende de la división elegida, como en el ejemplo de referencia.
function monthsSpanned(events) {
  if (!events.length) return [];
  const toDate = (s) => new Date(s + "T00:00:00");
  const min = new Date(Math.min(...events.map((e) => toDate(e.start))));
  const max = new Date(Math.max(...events.map((e) => toDate(e.end))));
  const months = [];
  let y = min.getFullYear(), m = min.getMonth();
  while (y < max.getFullYear() || (y === max.getFullYear() && m <= max.getMonth())) {
    months.push({ y, m });
    m++;
    if (m > 11) { m = 0; y++; }
  }
  return months;
}

const MONTH_NAMES = ["Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic"];
const WEEKDAY_LETTERS = ["D", "L", "M", "M", "J", "V", "S"];

// Calendario visual mes a mes: cada día se pinta con el color del período que le toca
// a la división elegida (o verde = contacto normal, si no cae en ningún período especial).
function RecruitingMonthCalendar({ events, division }) {
  const divEvents = events.filter((e) => e.div === division);
  if (!divEvents.length) return null;
  const months = monthsSpanned(events);
  const today = isoDate(new Date().getFullYear(), new Date().getMonth(), new Date().getDate());

  const colorFor = (dateStr) => {
    const hit = divEvents.find((e) => dateStr >= e.start && dateStr <= e.end);
    return hit ? { color: PERIOD_TYPE_COLOR[hit.type] || "#888", type: hit.type, label: hit.label } : { color: PERIOD_TYPE_COLOR.contact, type: "contact", label: "Período de contacto" };
  };

  return (
    <div>
      <div className="rm-cal-legend">
        {Object.entries(PERIOD_TYPE_COLOR).filter(([t]) => divEvents.some((e) => e.type === t) || t === "contact").map(([t, c]) => (
          <span key={t} className="rm-cal-legend-item"><i style={{ background: c }} />{PERIOD_TYPE_LABEL[t] || t}</span>
        ))}
      </div>
      <div className="rm-cal-months">
        {months.map(({ y, m }) => {
          const numDays = new Date(y, m + 1, 0).getDate();
          const firstWeekday = new Date(y, m, 1).getDay();
          const cells = [];
          for (let i = 0; i < firstWeekday; i++) cells.push(null);
          for (let d = 1; d <= numDays; d++) cells.push(d);
          return (
            <div className="rm-cal-month" key={`${y}-${m}`}>
              <div className="rm-cal-month-title">{MONTH_NAMES[m]} {y}</div>
              <div className="rm-cal-weekdays">{WEEKDAY_LETTERS.map((w, i) => <span key={i}>{w}</span>)}</div>
              <div className="rm-cal-days">
                {cells.map((d, i) => {
                  if (d === null) return <span key={i} className="rm-cal-day rm-cal-day-empty" />;
                  const dateStr = isoDate(y, m, d);
                  const info = colorFor(dateStr);
                  const isToday = dateStr === today;
                  return (
                    <span key={i} className={`rm-cal-day${isToday ? " rm-cal-day-today" : ""}`} style={{ background: info.color }} title={`${dateStr} — ${info.label}`}>
                      {d}
                    </span>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

